func testTipoCombustivelToManyAddOpTCBNotaFiscalItemVeiculos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a TipoCombustivel
	var b, c, d, e NotaFiscalItemVeiculo

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, tipoCombustivelDBTypes, false, strmangle.SetComplement(tipoCombustivelPrimaryKeyColumns, tipoCombustivelColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*NotaFiscalItemVeiculo{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, notaFiscalItemVeiculoDBTypes, false, strmangle.SetComplement(notaFiscalItemVeiculoPrimaryKeyColumns, notaFiscalItemVeiculoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*NotaFiscalItemVeiculo{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddTCBNotaFiscalItemVeiculos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.TCBID != first.TCBID {
			t.Error("foreign key was wrong value", a.TCBID, first.TCBID)
		}
		if a.TCBID != second.TCBID {
			t.Error("foreign key was wrong value", a.TCBID, second.TCBID)
		}

		if first.R.TCB != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.TCB != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.TCBNotaFiscalItemVeiculos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.TCBNotaFiscalItemVeiculos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.TCBNotaFiscalItemVeiculos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

